@js:
// 一一映射到unicode私有字符区间0xE800-0xE863，共100个字符
const hz = "的一是了我不人在他有这个上们来到时大地为子中你说生国年着就那和要她出也得里后自以会家可下而过天去能对小多然于心学么之都好看起发当没成只如事把还用第样道想作种开美乳阴液茎欲呻肉交性胸私穴淫臀舔射脱裸骚唇";

result.replace(/[\ue800-\ue863]/gi, m => hz[m.charCodeAt(0) - 0xe800] ?? m);

ruleToc.chapterUrl:
@js:
(() => {
  let a = result.selectFirst("a");
  if(!a) return "";
  let href = a.attr("href");
  if(!href.contains("javascript")) return href;

  let prev = result.previousElementSibling();
  let prevUrl = prev.selectFirst("a")?.attr("href");
  return String(prevUrl).replace(/\d+(?=\.html)/, m => +m + 1);
})()
